from openpyxl import load_workbook
from pathlib import Path
path=Path('/root/output/result.xlsx')
wb=load_workbook(path, data_only=False)
ws=wb['Task']
print('Sheets:', wb.sheetnames)
assert wb.sheetnames == ['Task','Data'], wb.sheetnames

def is_formula(v):
    return isinstance(v, str) and v.startswith('=')
checks = {
    'lookup H12:L17': (range(12,18), range(8,13)),
    'lookup H19:L24': (range(19,25), range(8,13)),
    'lookup H26:L31': (range(26,32), range(8,13)),
    'net H35:L40': (range(35,41), range(8,13)),
    'summary H42:L47': (range(42,48), range(8,13)),
    'weighted H50:L50': ([50], range(8,13)),
}
for name,(rows,cols) in checks.items():
    missing=[]
    for r in rows:
        for c in cols:
            if not is_formula(ws.cell(r,c).value):
                missing.append(ws.cell(r,c).coordinate+':'+repr(ws.cell(r,c).value))
    print(name, 'OK' if not missing else 'MISSING '+str(missing[:10]))
    assert not missing

# Check formulas conform to expected references.
samples = ['H12','L17','H19','L24','H26','L31','H35','L40','H42','H43','H44','H45','H46','H47','H50','L50']
print('\nSample formulas:')
for coord in samples:
    print(coord, ws[coord].value)

# Print compact populated target area formulas.
print('\nRows 12-17 H:L')
for r in range(12,18): print(r, [ws.cell(r,c).value for c in range(8,13)])
print('\nRows 35-50 H:L (selected nonblank/formula rows)')
for r in list(range(35,41))+list(range(42,48))+[50]:
    print(r, [ws.cell(r,c).value for c in range(8,13)])

# Verify weighted formulas use SUMPRODUCT in all cells.
for c in range(8,13):
    v=ws.cell(50,c).value
    assert 'SUMPRODUCT' in v and f'{ws.cell(35,c).coordinate}:{ws.cell(40,c).coordinate}' in v
print('\nVerification passed.')
